-- LOCAL DEVELOPMENT ONLY. `supabase db reset` runs this AFTER all migrations.
-- `supabase db push` does not apply seed.sql. Never run this seed against a
-- staging/production database: these accounts have a published test password.
-- Sign in at /login with any email below and password LocalTest123!
--
-- Distinct UUID prefixes keep the referral codes generated by handle_new_user
-- unique. Inserting users fires the profile/cart triggers from the migrations.
set search_path = public, extensions;

insert into auth.users (
  instance_id, id, aud, role, email, encrypted_password,
  email_confirmed_at, raw_app_meta_data, raw_user_meta_data,
  confirmation_token, recovery_token, email_change, email_change_token_new,
  created_at, updated_at
)
select
  '00000000-0000-0000-0000-000000000000'::uuid,
  demo.id, 'authenticated', 'authenticated', demo.email,
  crypt('LocalTest123!', gen_salt('bf')),
  now(), '{"provider":"email","providers":["email"]}'::jsonb,
  jsonb_build_object('display_name', demo.display_name),
  '', '', '', '', now(), now()
from (values
  ('a11ce001-0000-4000-8000-000000000001'::uuid, 'admin@example.test', 'Local Admin'),
  ('e11ce002-0000-4000-8000-000000000002'::uuid, 'employee@example.test', 'Local Employee'),
  ('c115e003-0000-4000-8000-000000000003'::uuid, 'customer@example.test', 'Local Customer')
) as demo(id, email, display_name)
on conflict (id) do nothing;

-- Current Supabase Auth stores the email/password provider on auth.identities.
-- provider_id is the user UUID as text; id has its own UUID default.
insert into auth.identities (
  provider_id, user_id, identity_data, provider,
  last_sign_in_at, created_at, updated_at
)
select u.id::text, u.id,
  jsonb_build_object('sub', u.id::text, 'email', u.email, 'email_verified', true, 'phone_verified', false),
  'email', null, now(), now()
from auth.users u
where u.id in (
  'a11ce001-0000-4000-8000-000000000001',
  'e11ce002-0000-4000-8000-000000000002',
  'c115e003-0000-4000-8000-000000000003'
)
on conflict (provider_id, provider) do nothing;

-- The signup trigger creates customer profiles for all three users. Promote
-- the test admin, assign the employee to the seeded Hong Kong location, and leave
-- the customer unassigned so the normal /locations picker controls pickup.
update public.profiles p set
  role = demo.role,
  location_id = demo.location_id,
  display_name = demo.display_name,
  is_active = true,
  -- The demo employee keeps their location-scoped duties and gains one module
  -- so the permission-gated admin console is visible on a fresh local reset.
  permissions = case when demo.role = 'employee' then '{"quotes.manage"}'::text[] else '{}'::text[] end
from (values
  ('a11ce001-0000-4000-8000-000000000001'::uuid, 'admin', null::uuid, 'Local Admin'),
  ('e11ce002-0000-4000-8000-000000000002'::uuid, 'employee', '00000000-0000-0000-0000-000000000001'::uuid, 'Local Employee'),
  ('c115e003-0000-4000-8000-000000000003'::uuid, 'customer', null::uuid, 'Local Customer')
) as demo(id, role, location_id, display_name)
where p.id = demo.id;

reset search_path;
